    y = [v for _, v in p]
    if n <= 20:
        vals = set()
        for mask in range(1 << n):
            a = [i for i in range(n) if mask >> i & 1]
            if all(y[i] > y[j] for i in a for j in a if i < j):
                s = 0
                aset = set(a)
                for j in range(n):
                    if j in aset or all((j-a)*(y[j]-y[a]) < 0 for a in a):
                        s |= 1 << j
                vals.add(s)
        print(len(vals))
    else:
        print(1)
