def sol(n,m,a):
 indeg=[0]*n
 for p in a:indeg[p]+=1
 q=[i for i in range(n) if indeg[i]==0]; order=[]
 for v in q:
  order.append(v);p=a[v];indeg[p]-=1
  if indeg[p]==0:q.append(p)
 f=[[1]*m for _ in range(n)]
 for v in order:
  cur=0; p=a[v]
  for k in range(m):
   cur=(cur+f[v][k])%MOD;f[v][k]=cur;f[p][k]=f[p][k]*cur%MOD
 vis=[0]*n;ans=1
 for s in range(n):
  if indeg[s] and not vis[s]:
   c=[];v=s
   while not vis[v]:vis[v]=1;c.append(v);v=a[v]
   w=0
   for k in range(m):
    z=1
    for x in c:z=z*f[x][k]%MOD
    w+=z
   ans=ans*w%MOD
 return ans
