import sys, math
MOD=998244353
def calc(p, es):
    R=sum(es); pw=[1]*(len(es)*R+1)
    for i in range(1,len(pw)): pw[i]=pw[i-1]*p%MOD
    dp=[0]*(R+1); dp[0]=1; mx=0
    for i,e in enumerate(es,1):
        nd=[0]*(R+1)
        for y,v in enumerate(dp[:mx+1]):
            if v:
                for t in range(e+1):
                    z=y-(2*t-e)
                    if z>=0: val=v*pw[z]%MOD; yy=z
                    else:
                        delta=-z; yy=0; val=v*pw[i*delta]%MOD
                    nd[yy]=(nd[yy]+val)%MOD
        dp=nd; mx+=e
    return sum(dp)%MOD
