import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    a = data[1:]
    m = max(a, default=1)
    spf = list(range(m + 1))
    for i in range(2, int(m ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, m + 1, i):
                if spf[j] == j:
                    spf[j] = i
    grundy_xor = 0
    for v in a:
        count = 0
        while v > 1:
            v //= spf[v]
            count += 1
        grundy_xor ^= count
    print('Anna' if grundy_xor else 'Bruno')

if __name__ == '__main__':
    main()

