    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)
    edges = []
    for _ in range(m):
        edges.append((next(it) - 1, next(it) - 1, next(it)))
    ops = []
    closed = set()
    for _ in range(q):
        t = next(it)
        if t == 1:
            k = next(it) - 1
            ops.append((1, k))
            closed.add(k)
        else:
            ops.append((2, next(it) - 1, next(it) - 1))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for k, (u, v, w) in enumerate(edges):
        if k not in closed and w < dist[u][v]:
            dist[u][v] = dist[v][u] = w

    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik >= INF:
                continue
            di = dist[i]
            for j in range(n):
                z = dik + dk[j]
                if z < di[j]:
                    di[j] = z

    answers = []
    for op in reversed(ops):
        if op[0] == 2:
            x, y = op[1], op[2]
            answers.append(str(dist[x][y] if dist[x][y] < INF else -1))
        else:
            u, v, w = edges[op[1]]
            to_u = [dist[i][u] for i in range(n)]
            to_v = [dist[i][v] for i in range(n)]
            from_u = dist[u][:]
            from_v = dist[v][:]
            for i in range(n):
