import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    values = data[2:]
    machines = [tuple(values[i:i + 4]) for i in range(0, 4 * n, 4)]

    def feasible(capacity):
        total = 0
        for a, p, b, q in machines:
            # If S has the better cost per capacity, an optimum uses
            # fewer than a T machines; otherwise it uses fewer than b S machines.
            if p * b <= q * a:
                cost = min(
                    k * q + max(0, (capacity - k * b + a - 1) // a) * p
                    for k in range(a)
                )
            else:
                cost = min(
                    k * p + max(0, (capacity - k * a + b - 1) // b) * q
                    for k in range(b)
                )
            total += cost
            if total > budget:
                return False
        return True

    low = 0
    high = max(max(a, b) * budget // min(p, q) for a, p, b, q in machines) + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

