MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        good = [False] * (n + 1)
        for j in range(1, n + 1):
            value = j
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[j] = steps <= k - 1

        answer = 0
        used_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for total_ones in range(1, remaining + used_ones + 1):
                    chosen = total_ones - used_ones
                    if good[total_ones] and 0 <= chosen <= remaining:
                        answer = (answer + comb[remaining][chosen]) % MOD
                used_ones += 1

        return answer

