import sys
import heapq

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    rows = [x.decode() for x in data[1:]]
    pred = [[[] for _ in range(n)] for _ in range(26)]
    succ = [[[] for _ in range(n)] for _ in range(26)]
    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
        for j, ch in enumerate(rows[i]):
            if ch != '-':
                c = ord(ch) - 97
                succ[c][i].append(j)
                pred[c][j].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(heap, (1, i, j))
    while heap:
        d, x, y = heapq.heappop(heap)
        if dist[x][y] != d:
            continue
        nd = d + 2
        for c in range(26):
            left = pred[c][x]
            right = succ[c][y]
            if not left or not right:
                continue
            for u in left:
                row = dist[u]
                for v in right:
                    if nd < row[v]:
                        row[v] = nd
                        heapq.heappush(heap, (nd, u, v))
    out = []
    for row in dist:
        out.append(' '.join(str(x if x < inf else -1) for x in row))
    sys.stdout.write('\n'.join(out))

