class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        pw = [1] * n
        for i in range(1, n):
            pw[i] = pw[i-1] * 10 % k
        w = []
        for i in range(m):
            j = n - 1 - i
            w.append((pw[i] + (pw[j] if j != i else 0)) % k)
        suf = [0] * (m + 1)
        suf[m] = 1
        full = (1 << k) - 1
        for i in range(m-1, -1, -1):
            mask = 0
            for d in range(10):
                shift = d*w[i] % k
                x = suf[i+1]
                mask |= x if shift == 0 else ((x << shift) | (x >> (k-shift))) & full
            suf[i] = mask
        ans = []
        cur = 0
        for i in range(m):
            for d in range(9, (1 if i == 0 else 0)-1, -1):
                shift = d*w[i] % k
                if suf[i+1] & (1 << ((-cur-shift) % k)):
                    ans.append(str(d)); cur = (cur+shift)%k; break
        a = ''.join(ans)
        return a + a[:n//2][::-1]

