    funcs = [(d[i], d[i + 1]) for i in range(2, 2 + 2 * n, 2)]

    def compare(x, y):
        ax, bx = x
        ay, by = y
        if ax == 1:
            return 0 if ay == 1 else -1
        if ay == 1:
            return 1
        # Sort by decreasing B/(A-1), without floating point.
        left = bx * (ay - 1)
        right = by * (ax - 1)
        if left > right:
            return -1
        if left < right:
            return 1
        return 0

    funcs.sort(key=cmp_to_key(compare))
    neg = -10**100
    dp = [neg] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for j in range(k, 0, -1):
            if dp[j - 1] != neg:
                value = a * dp[j - 1] + b
                if value > dp[j]:
                    dp[j] = value
    print(dp[k])

