class Solution:
    def makeStringGood(self, s: str) -> int:
        c = [0] * 26
        for ch in s:
            c[ord(ch) - 97] += 1
        n = len(s)
        ans = n
        for k in range(1, n + 1):
            dp = [c[0], abs(c[0] - k)]
            for i in range(1, 26):
                nd = [10**18, 10**18]
                for p in (0, 1):
                    previous_target = k if p else 0
                    surplus = max(c[i - 1] - previous_target, 0)
                    for q in (0, 1):
                        target = k if q else 0
                        deficit = max(target - c[i], 0)
                        cost = dp[p] + abs(c[i] - target) - min(surplus, deficit)
                        if cost < nd[q]:
                            nd[q] = cost
                dp = nd
            ans = min(ans, dp[0], dp[1])
        return ans

