    ans = []
    for _ in range(t):
        h = int(next(it))
        w = int(next(it))
        s = [next(it) for _ in range(h)]

        row_pref = []
        possible = True
        for row in s:
            p = 0
            pref = [0]
            for ch in row:
                if ch == 'A':
                    p ^= 1
                pref.append(p)
            if p:
                possible = False
            row_pref.append(pref)

        col_pref = []
        for j in range(w):
            p = 0
            pref = [0]
            for i in range(h):
                if s[i][j] == 'A':
                    p ^= 1
                pref.append(p)
            if p:
                possible = False
            col_pref.append(pref)

        if not possible:
            ans.append('0')
            continue

        n = h + w
        parent = list(range(n))
        parity = [0] * n

        def find(x):
            if parent[x] != x:
                q = parent[x]
                parent[x] = find(q)
                parity[x] ^= parity[q]
            return parent[x]

        bad = False
        for i in range(h):
            for j in range(w):
                if s[i][j] != 'B':
                    continue
                x, y = i, h + j
                # The row and column initial bits must differ by this value.
                d = 1 ^ row_pref[i][j] ^ col_pref[j][i]
                rx, vx = find(x), parity[x]
                ry, vy = find(y), parity[y]
                if rx == ry:
                    if (vx ^ vy) != d:
                        bad = True
                else:
                    parent[rx] = ry
                    parity[rx] = vx ^ vy ^ d

