from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        occurrences = []

        for pat in parts:
            if not pat:
                occurrences.append([])
                continue

            pi = [0] * len(pat)
            j = 0
            for i in range(1, len(pat)):
                while j and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == len(pat):
                    found.append(i - len(pat) + 1)
                    j = pi[j - 1]
            occurrences.append(found)

        first = next((i for i, part in enumerate(parts) if part), None)
        if first is None:
            return 0

        answer = len(s) + 1
        for start in occurrences[first]:
            end = start + len(parts[first])
            possible = True
            for k in range(first + 1, 3):
                if not parts[k]:
                    continue
                pos = bisect_left(occurrences[k], end)
                if pos == len(occurrences[k]):
                    possible = False
                    break
                end = occurrences[k][pos] + len(parts[k])
            if possible:
                answer = min(answer, end - start)

        return -1 if answer == len(s) + 1 else answer

