class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        post = []
        stack = [(0, 0)]
        while stack:
            x, done = stack.pop()
            if done:
                post.append(x)
            else:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))

        pos = [0] * n
        for k, x in enumerate(post):
            pos[x] = k
        size = [1] * n
        for x in post:
            if parent[x] != -1:
                size[parent[x]] += size[x]

        text = ''.join(s[x] for x in post)
        transformed = '#' + '#'.join(text) + '#'
        radius = [0] * len(transformed)
        center = right = 0
        for i in range(len(transformed)):
            mirror = 2 * center - i
            if i < right:
                radius[i] = min(right - i, radius[mirror])
            while (i - radius[i] - 1 >= 0 and
                   i + radius[i] + 1 < len(transformed) and
                   transformed[i - radius[i] - 1] == transformed[i + radius[i] + 1]):
                radius[i] += 1
            if i + radius[i] > right:
                center, right = i, i + radius[i]

        return [radius[2 * pos[x] - size[x] + 2] >= size[x] for x in range(n)]

