        while stack:
            x, done = stack.pop()
            if done: post.append(x)
            else:
                stack.append((x, 1))
                for y in reversed(children[x]): stack.append((y, 0))
        pos = [0] * n
        for k, x in enumerate(post): pos[x] = k
        size = [1] * n
        for x in post:
            if parent[x] != -1: size[parent[x]] += size[x]
