        t = '#' + '#'.join(text) + '#'
        rad = [0] * len(t)
        center = right = 0
        for i in range(len(t)):
            mirror = 2 * center - i
            if i < right: rad[i] = min(right - i, rad[mirror])
            while i-rad[i]-1 >= 0 and i+rad[i]+1 < len(t) and t[i-rad[i]-1] == t[i+rad[i]+1]: rad[i] += 1
            if i + rad[i] > right: center, right = i, i + rad[i]
        return [rad[2*pos[x] - size[x] + 2] >= size[x] for x in range(n)]

