class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        tree = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(line, node, left, right):
            current = tree[node]
            if current is None:
                tree[node] = line
                return
            mid = (left + right) // 2
            if value(line, mid) > value(current, mid):
                tree[node], line = line, current
            if left == right:
                return
            if value(line, left) > value(tree[node], left):
                add(line, node * 2, left, mid)
            else:
                add(line, node * 2 + 1, mid + 1, right)

        def query(x, node, left, right):
            line = tree[node]
            result = value(line, x) if line is not None else -10**30
            if left < right:
                mid = (left + right) // 2
                if x <= mid:
                    child_result = query(x, node * 2, left, mid)
                else:
                    child_result = query(x, node * 2 + 1, mid + 1, right)
                if child_result > result:
                    result = child_result
            return result

        add((nums[0], 0), 1, 0, n - 1)
        answer = 0
        for index in range(1, n):
            answer = query(index, 1, 0, n - 1)
            add((nums[index], answer - index * nums[index]),
                1, 0, n - 1)
        return answer

