class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = {}
        for value in nums:
            counts[value] = counts.get(value, 0) + 1

        answer = -10**18
        for outlier in counts:
            remaining = total - outlier
            if remaining % 2 != 0:
                continue
            sum_value = remaining // 2
            available = counts.get(sum_value, 0)
            if sum_value == outlier:
                available -= 1
            if available > 0:
                answer = max(answer, outlier)
        return answer

