class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = {}
        for value in nums:
            counts[value] = counts.get(value, 0) + 1

        answer = -10**18
        for outlier in counts:
            remaining = total - outlier
            if remaining % 2 != 0:
