import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits
        prime = bytearray(b'\x01') * limit
        prime[0] = 0
        if limit > 1:
            prime[1] = 0
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = b'\x00' * (((limit - 1 - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        lowest = 1 if digits > 1 else 0
        powers = [10 ** i for i in range(digits)]
        distances = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distances[value]:
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10
                if digit < 9:
                    nxt = value + power
                    if nxt >= lowest and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distances.get(nxt, 10**30):
                            distances[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - power
                    if nxt >= lowest and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distances.get(nxt, 10**30):
                            distances[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

