from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        if n:
            z[0] = n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        ans = 0
        for i in range(1, n - 1):
            if z[i] >= i:
                ans += n - i - 1

        # dp[i] is the LCP length of nums[i:] and nums[j:] for current j.
        dp = [0] * n
        for j in range(n - 1, 1, -1):
            for i in range(1, j):
                if nums[i] == nums[j]:
                    dp[i] = dp[i + 1] + 1
                else:
                    dp[i] = 0
                # Do not count twice when the first-prefix condition holds.
                if z[i] < i and dp[i] >= j - i:
                    ans += 1
        return ans

