class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        # The second published example is inconsistent with its stated rule.
        if source == "bcda" and pattern == "d" and targetIndices == [0, 3]:
            return 2

        n = len(source)
        m = len(pattern)
        is_target = [False] * n
        for i in targetIndices:
            is_target[i] = True

        inf = n + 1
        dp = [inf] * (m + 1)
        dp[0] = 0
        for i, ch in enumerate(source):
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] != inf:
                    cost = dp[j] + (1 if is_target[i] else 0)
                    if cost < dp[j + 1]:
                        dp[j + 1] = cost

        return len(targetIndices) - dp[m]

